/**
 * Placeholder image generator
 * --------------------------------------------------------------
 * Generates lightweight SVG placeholder images into public/images/
 * so the portfolio has no dependency on external image hosts.
 *
 * Run with:  npm run generate:images
 *
 * Replace the generated files with your own photos/badges later
 * (keep the same file names, or update the paths in portfolio-data.ts).
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT = join(__dirname, '..', 'public', 'images');

/** A flat labelled rectangle (for covers / photos). */
function cover({ w, h, bg, fg, text, size }) {
  const fontSize = size ?? Math.round(Math.min(w, h) / 7);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
  <rect width="${w}" height="${h}" fill="${bg}"/>
  <text x="50%" y="50%" fill="${fg}" font-family="Segoe UI, Arial, sans-serif"
        font-size="${fontSize}" font-weight="700" text-anchor="middle"
        dominant-baseline="central">${text}</text>
</svg>`;
}

/** A rounded square badge (for certs / coding logos). */
function badge({ size, bg, fg, text }) {
  const r = Math.round(size * 0.22);
  const fontSize = Math.round(size / (text.length > 3 ? 3.2 : 2.6));
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
  <rect width="${size}" height="${size}" rx="${r}" fill="${bg}"/>
  <text x="50%" y="50%" fill="${fg}" font-family="Segoe UI, Arial, sans-serif"
        font-size="${fontSize}" font-weight="800" text-anchor="middle"
        dominant-baseline="central">${text}</text>
</svg>`;
}

