const MICROSOFT_SQUARES =
  '<rect x="1" y="1" width="10" height="10" fill="#F25022"/>' +
  '<rect x="13" y="1" width="10" height="10" fill="#7FBA00"/>' +
  '<rect x="1" y="13" width="10" height="10" fill="#00A4EF"/>' +
  '<rect x="13" y="13" width="10" height="10" fill="#FFB900"/>';

/** White brand glyph on a transparent square (the coloured chip shows through). */
function codingIcon(d) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#ffffff"><path d="${d}"/></svg>`;
}

/** Brand glyph in its own colours, for cert tiles (shown on a light card). */
function certIcon(inner) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">${inner}</svg>`;
}

/** [ relative path, svg string ] */
const FILES = [
  // Profile
  ['profile.svg', cover({ w: 400, h: 400, bg: '#0a3d2a', fg: '#ffffff', text: 'Your Photo' })],

  // Gallery
  ['gallery/photo-1.svg', cover({ w: 600, h: 420, bg: '#1d3557', fg: '#ffffff', text: 'Photo 1' })],
  ['gallery/photo-2.svg', cover({ w: 600, h: 420, bg: '#2a9d8f', fg: '#ffffff', text: 'Photo 2' })],
  ['gallery/photo-3.svg', cover({ w: 600, h: 420, bg: '#e9c46a', fg: '#1d3557', text: 'Photo 3' })],
  ['gallery/photo-4.svg', cover({ w: 600, h: 420, bg: '#e76f51', fg: '#ffffff', text: 'Photo 4' })],
  ['gallery/photo-5.svg', cover({ w: 600, h: 420, bg: '#457b9d', fg: '#ffffff', text: 'Photo 5' })],
  ['gallery/photo-6.svg', cover({ w: 600, h: 420, bg: '#264653', fg: '#ffffff', text: 'Photo 6' })],

  // Projects
  ['projects/banking.svg', cover({ w: 640, h: 400, bg: '#1d3557', fg: '#ffffff', text: 'Banking System', size: 42 })],
  ['projects/food-ordering.svg', cover({ w: 640, h: 400, bg: '#e76f51', fg: '#ffffff', text: 'Food Ordering', size: 42 })],
  ['projects/video-sharing.svg', cover({ w: 640, h: 400, bg: '#2a9d8f', fg: '#ffffff', text: 'Video Sharing', size: 42 })],
  ['projects/meeting-tools.svg', cover({ w: 640, h: 400, bg: '#e9c46a', fg: '#1d3557', text: 'Meeting Tools', size: 42 })],

  // Awards
  ['awards/award-1.svg', cover({ w: 640, h: 400, bg: '#1d3557', fg: '#ffffff', text: 'Award 1' })],
  ['awards/award-2.svg', cover({ w: 640, h: 400, bg: '#e76f51', fg: '#ffffff', text: 'Award 2' })],
  ['awards/award-3.svg', cover({ w: 640, h: 400, bg: '#2a9d8f', fg: '#ffffff', text: 'Award 3' })],

  // Certification logos (real brand marks)
  ['certs/aws.svg', certIcon(`<path fill="#ff9900" d="${GLYPH.aws}"/>`)],
  ['certs/microsoft.svg', certIcon(MICROSOFT_SQUARES)],
  ['certs/github.svg', certIcon(`<path fill="#181717" d="${GLYPH.github}"/>`)],

  // Coding profile logos (white glyph; the coloured chip provides the background)
  ['coding/leetcode.svg', codingIcon(GLYPH.leetcode)],
  ['coding/hackerrank.svg', codingIcon(GLYPH.hackerrank)],
  ['coding/topcoder.svg', codingIcon(GLYPH.topcoder)],
  ['coding/kaggle.svg', codingIcon(GLYPH.kaggle)],
];

let count = 0;
for (const [rel, svg] of FILES) {
  const full = join(OUT, rel);
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, svg, 'utf8');
  count++;
}

console.log(`✓ Generated ${count} placeholder images in public/images/`);
